update public.products set image_url = '/images/clarity1.png', rich_content = '{"faq":[{"answer":"No. The mental clarity comes purely from the natural nootropic compounds in the mushrooms, so you will not experience jitteriness or a racing heart.","question":"Does it contain caffeine?"},{"answer":"The functional extracts are adaptogenic and help regulate the nervous system. Even so, we recommend taking them in the first half of the day.","question":"Will it affect my sleep?"}],"reviews":[{"date":"08 August 2026","author":"George I.","rating":5,"comment":"I replaced my second coffee of the day with this extract. Incredible focus - I can spend 4 hours glued to the monitor without losing concentration."},{"date":"17 July 2026","author":"Diana M.","rating":5,"comment":"Very good for students during exams! I recommend it 100%."}],"banner_text":"Top mental clarity, steady energy and zero brain fog!","content_image":"/clarity1.png","why_recommend":["100% fruiting body extract (no grain-grown mycelium)","Dual extraction to maximize the active compounds","An adaptogenic effect: it calms and focuses you at the same time"],"ingredients_table":[{"vnr":"**","name":"Concentrated extract (dual extract 10:1)","quantity":"1000 mg"},{"vnr":"**","name":"Active beta-glucans","quantity":"300 mg"},{"vnr":"**","name":"V-Caps® capsule","quantity":"100 mg"},{"vnr":"**","name":"Bamboo extract (source of silicon)","quantity":"25 mg"},{"vnr":"**","name":"Organic rice powder","quantity":"30 mg"}],"intro_description":"<p>Enjoy deep concentration, a sharp memory and mental clarity without the energy crashes that come with caffeine. Our standardized extracts from functional mushrooms and adaptogens are superfoods for your brain.</p><p>It supports neurogenesis (the formation of new neurons) and clears away the “brain fog” even on the busiest and most stressful working days.</p>"}'::jsonb where id = '238fe37c-7c2e-4d3d-baf4-60bf6a21964e';
update public.products set image_url = '/images/longevity4.png', rich_content = '{"faq":[{"answer":"We recommend 1-2 capsules a day, in the morning with a glass of water, to maximize the rate of cellular absorption throughout the day.","question":"What is the recommended dose?"},{"answer":"The rise in energy is felt within 7-14 days, but deep cellular repair calls for a course of at least 3 months for the best results.","question":"How soon will I see the anti-aging effects?"},{"answer":"Yes. The active substances are 100% bio-identical to the molecules the human body already produces, making them completely safe and non-toxic.","question":"Is it safe to take long term?"}],"reviews":[{"date":"10 July 2026","author":"Victor M.","rating":5,"comment":"I have been using it for 2 months and I have noticed a dramatic improvement in my stamina. I do not tire as quickly any more."},{"date":"22 June 2026","author":"Simone T.","rating":5,"comment":"My blood tests have improved since I started using your longevity products. Happy to recommend them!"},{"date":"05 May 2026","author":"Andrew G.","rating":4,"comment":"A very good supplement. The price is fair for the quality you get."}],"banner_text":"Activate cellular renewal and live at your full potential!","content_image":"/longevity4.png","why_recommend":["Independently tested purity > 99%","A stabilized formula for maximum bioavailability","No adverse effects, safe for daily use","Fights oxidative stress from the very first dose"],"ingredients_table":[{"vnr":"**","name":"Purified extract (99%)","quantity":"400 mg"},{"vnr":"**","name":"Liposomal absorption complex","quantity":"50 mg"},{"vnr":"**","name":"Vegetable capsule (HPMC)","quantity":"110 mg"},{"vnr":"**","name":"Microcrystalline cellulose","quantity":"30 mg"},{"vnr":"**","name":"Vegetable magnesium stearate","quantity":"5 mg"}],"intro_description":"<p>A state-of-the-art formula designed to slow down cellular aging. Acting directly at the level of the mitochondria, this supplement stimulates longevity and vitality from the inside out.</p><p>By activating the natural process of autophagy (the clearing of senescent cells), your body regains the energy and the capacity for regeneration of its younger years.</p>"}'::jsonb where id = '8d23801d-8cf5-411a-9302-0a66b83d484f';

