-- Verificare: nicio cale nu mai trebuie sa contina nume romanesti.
do $$
declare nr int;
begin
  select count(*) into nr from public.products
   where image_url ~ 'claritate|longevitate|calitate_'
      or rich_content::text ~ 'claritate|longevitate|calitate_';
  if nr > 0 then raise exception 'OPRIT: % produse au inca imagini cu nume romanesc.', nr; end if;

  select count(*) into nr from public.calitate_content where image_url ~ 'calitate_|claritate|longevitate';
  if nr > 0 then raise exception 'OPRIT: % randuri calitate_content au inca imagini cu nume romanesc.', nr; end if;

  select count(*) into nr from public.journal_articles where image_url ~ 'calitate_|claritate|longevitate';
  if nr > 0 then raise exception 'OPRIT: % articole au inca imagini cu nume romanesc.', nr; end if;
end $$;

commit;
